layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); background-color: rgb(232, 213, 215); border-top: 1px inset var(--ryt-border); border-right: 1px inset var(--ryt-border); border-bottom: 1px inset var(--ryt-border); border-left: 1px inset var(--ryt-border); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 11px; font-weight: 400; font-style: italic; line-height: 1.4; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 8px; padding-bottom: 8px; padding-left: 8px; transition: all }
[data-ryt="footer"] { color: var(--ryt-muted); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: rgb(240, 240, 240); border-top: 1px outset var(--ryt-border); border-right: 1px outset var(--ryt-border); border-bottom: 1px outset var(--ryt-border); border-left: 1px outset var(--ryt-border); border-radius: 0px; transition: all }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 2px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: #808080; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 11px; font-weight: 700; font-style: normal; line-height: 1.4; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(255, 255, 255); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: color-mix(in srgb, var(--ryt-text) 30%, transparent) 1px 1px 0px; transition: all }
[data-ryt="nav"] a { color: var(--ryt-text); background-color: rgb(192, 192, 192); border-top: 1px outset rgb(192, 192, 192); border-right: 1px outset rgb(192, 192, 192); border-bottom: 1px outset rgb(192, 192, 192); border-left: 1px outset rgb(192, 192, 192); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 11px; font-weight: 400; font-style: normal; line-height: 1.4; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 4px; padding-right: 8px; padding-bottom: 4px; padding-left: 8px; transition: all }
[data-ryt="button"] { color: var(--ryt-text); background-color: rgb(192, 192, 192); border-top: 1px outset rgb(192, 192, 192); border-right: 1px outset rgb(192, 192, 192); border-bottom: 1px outset rgb(192, 192, 192); border-left: 1px outset rgb(192, 192, 192); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: 1.4; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 4px; padding-right: 8px; padding-bottom: 4px; padding-left: 8px; transition: all }
[data-ryt="category"], [data-ryt="tags"] li { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: 1.4; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 10px; font-weight: 400; font-style: normal; line-height: 1.3; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 10px; font-weight: 400; font-style: normal; line-height: 1.4; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 11px; font-weight: 700; font-style: normal; line-height: 1.4; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]:hover { color: #0000EE }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #0000EE }
[data-ryt="button"]:hover { color: rgb(255, 255, 255) }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
